import inspect
import numpy as np
import mteb

MODEL = "BAAI/bge-small-zh-v1.5"
REV = "7999e1d3359715c523056ef9478215996d62a620"
QUERY = "terminal-bench"

docs = [l.rstrip("\n") for l in open("data.txt", encoding="utf-8") if l.strip()]
model = mteb.get_model(MODEL, revision=REV)


def encode(texts, kind):
    fn = model.encode
    params = inspect.signature(fn).parameters
    kw = {}
    accepts = lambda n: n in params or any(
        p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()
    )
    if accepts("task_metadata"):
        # newer mteb passes task metadata; omit prompts entirely
        pass
    for name, val in (("prompt_type", kind), ("task_name", "Retrieval")):
        if name in params:
            kw[name] = val
    try:
        return np.asarray(fn(texts, **kw))
    except TypeError:
        return np.asarray(fn(texts))


try:
    from mteb.encoder_interface import PromptType
    qtype, dtype = PromptType.query, PromptType.document
except Exception:
    qtype, dtype = "query", "document"

q = encode([QUERY], qtype)
d = encode(docs, dtype)
norm = lambda x: x / np.linalg.norm(x, axis=1, keepdims=True)
sims = (norm(d) @ norm(q).T).ravel()
order = np.argsort(-sims)
for i in order[:8]:
    print(round(float(sims[i]), 4), docs[i])
best = docs[order[4]]
open("result.txt", "w", encoding="utf-8").write(best + "\n")
print("RESULT:", best)
EOF
python solve.py 2>&1 | tail -20

