cd /app && cat > solve.py <<'EOF'
"""Rank /app/data.txt lines by cosine similarity to the query using
bge-small-zh-v1.5 loaded through the public mteb API; write the 5th best."""
from __future__ import annotations

import inspect

import numpy as np
import mteb

MODEL = "BAAI/bge-small-zh-v1.5"
REVISION = "7999e1d3359715c523056ef9478215996d62a620"
QUERY = "terminal-bench"
TASK_NAME = "T2Retrieval"  # a real mteb retrieval task (needed by some versions)

docs = [line.rstrip("\n") for line in open("/app/data.txt", encoding="utf-8") if line.strip()]

model = mteb.get_model(MODEL, revision=REVISION)


def encode(texts: list[str]) -> np.ndarray:
    """Version-tolerant call of the public Encoder.encode API."""
    fn = model.encode
    try:
        params = inspect.signature(fn).parameters
    except (TypeError, ValueError):
        params = {}
    kwargs = {}
    if "task_name" in params:
        kwargs["task_name"] = TASK_NAME
    if "task_metadata" in params:
        try:
            kwargs["task_metadata"] = mteb.get_task(TASK_NAME).metadata
        except Exception:
            pass
    for attempt in (kwargs, {"task_name": TASK_NAME}, {}):
        try:
            return np.asarray(fn(texts, **attempt), dtype=np.float64)
        except TypeError:
            continue
    raise RuntimeError("could not call model.encode")


def unit(x: np.ndarray) -> np.ndarray:
    return x / np.linalg.norm(x, axis=1, keepdims=True)


emb = encode([QUERY] + docs)
sims = (unit(emb[1:]) @ unit(emb[:1]).T).ravel()
order = np.argsort(-sims)
for rank, idx in enumerate(order[:8], 1):
    print(rank, round(float(sims[idx]), 4), docs[idx])

result = docs[order[4]]
with open("/app/result.txt", "w", encoding="utf-8") as f:
    f.write(result + "\n")
print("RESULT:", result)
EOF
python solve.py 2>&1 | tail -10 && echo --- && cat /app/result.txt

